'''/**
 * A key may carry a subject after its bucket name (`auth:password-reset:<email>`)
 * so one bucket shape can be metered per subject; such a key takes the shape of
 * the longest declared bucket it extends.
 */
export function getBucketConfig(bucketKey: string): RateLimitConfig {
  const exact = RATE_LIMIT_BUCKETS[bucketKey];
  if (exact) return exact;

  let best: string | null = null;
  for (const name of Object.keys(RATE_LIMIT_BUCKETS)) {
    if (
      bucketKey.startsWith(`${name}:`) &&
      (best === null || name.length > best.length)
    ) {
      best = name;
    }
  }
  return (best === null ? undefined : RATE_LIMIT_BUCKETS[best]) ?? DEFAULT_BUCKET;
}

/**
 * Bucket key metered per subject (an email address, a token digest) rather
 * than shared by everyone who reaches the endpoint. Case-insensitive.
 */
export function subjectBucketKey(bucketKey: string, subject: string): string {
  return `${bucketKey}:${subject.trim().toLowerCase()}`;
}''')])

